$ErrorActionPreference="Stop"
try{$R=Split-Path -Parent $MyInvocation.MyCommand.Path;Set-Location $R;if(!(Test-Path "docs\meridian-network")){throw "docs\meridian-network not found"};$bk="_backup_extraordinary32_"+(Get-Date -Format "yyyyMMdd-HHmmss");New-Item -ItemType Directory -Force $bk|Out-Null;foreach($s in Get-ChildItem "_payload\docs\meridian-network" -File){$d=Join-Path "docs\meridian-network" $s.Name;if(Test-Path $d){Copy-Item $d (Join-Path $bk $s.Name) -Force};Copy-Item $s.FullName $d -Force};Write-Host "EXTRAORDINARY VESSELS MODERNIZATION 32 COMPLETE" -ForegroundColor Green;Write-Host "Eight extraordinary-vessel pages rebuilt in place, not appended." -ForegroundColor Cyan;Write-Host ("Backup: "+$bk) -ForegroundColor Yellow}catch{Write-Host ("ERROR: "+$_.Exception.Message) -ForegroundColor Red};Read-Host "Press Enter to close"